const {Signale} =  require('signale')
var nanoid = require('nanoid')

const logger  = new Signale({
    scope : ' opensi-cli ',
    types: {
        loading: {
          badge: '◌',
          color: 'yellow',
          label: 'loading'
        },
        debug: {
            badge: '⬤',
            color: 'blue',
            label: 'verbose'
        }
    }
})

module.exports = {

    log: {
        e: logger.fatal,
        d: logger.debug,
        s: logger.success,
        p: logger.pending,
        w: logger.loading,
        c: logger.complete
    },
    uid(){
        return nanoid() //=> "V1StGXR8_Z5jdHi6B~myT"
    }
    
}